const tabId = 1148881640;

const extracted = await browserjs(tabId, () => {
  const days = [];
  const headings = Array.from(document.querySelectorAll('h2, h3'));

  // Let's find each date heading
  const dateRegex = /^(Mon|Tue|Wed|Thu|Fri|Sat|Sun)\s+(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)\s+\d+/i;

  headings.forEach(h => {
    const text = h.innerText.trim();
    if (dateRegex.test(text)) {
      // Find its parent container or sibling content
      let container = h.closest('section') || h.parentElement;
      // Let's collect all text or structured blocks inside this container
      days.push({
        date: text,
        containerText: container ? container.innerText : ''
      });
    }
  });

  return days;
});

console.log("Found date headings:", extracted.length);
extracted.forEach((d, idx) => {
  console.log(`--- Day ${idx + 1}: ${d.date} ---`);
  console.log(d.containerText);
});

