const domInfo = await browserjs(tabId, () => {
  const headings = Array.from(document.querySelectorAll('h2, h3'));
  const dateRegex = /^(Mon|Tue|Wed|Thu|Fri|Sat|Sun)\s+(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)\s+\d+/i;

  const targetHeadings = headings.filter(h => dateRegex.test(h.innerText.trim()));
  if (targetHeadings.length === 0) return "No target headings found";

  const sample = targetHeadings[1]; // Fri Sep 18
  let el = sample;
  const path = [];
  for (let i = 0; i < 5; i++) {
    if (!el) break;
    path.push({
      tag: el.tagName,
      className: el.className,
      childCount: el.children.length,
      textLength: el.innerText.length
    });
    el = el.parentElement;
  }
  return path;
});

